 "content": "def transform(grid):
    """Reflect an unmatched tile-object into its established partner tile."""
    h, w = len(grid), len(grid[0])
    hdiv = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    vdiv = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    rb, cb = [-1] + hdiv + [h], [-1] + vdiv + [w]
    rt = [(rb[i]+1, rb[i+1]) for i in range(len(rb)-1)]
    ct = [(cb[i]+1, cb[i+1]) for i in range(len(cb)-1)]
    out = [row[:] for row in grid]
    n = len(ct)

    def tile(r0, r1, j):
        c0, c1 = ct[j]
        return [[grid[r][c] for c in range(c0,c1)] for r in range(r0,r1)]
    def occupied(a):
        return any(v for row in a for v in row)
    def color(a):
        return next((v for row in a for v in row if v), 0)
    def mirror_equal(a,b):
        return (len(a)==len(b) and all(len(x)==len(y) for x,y in zip(a,b)) and
                all(a[r][c] == b[r][len(b[0])-1-c] for r in range(len(a)) for c in range(len(a[0]))))

    # Discover panel pairings from already-complete reflected examples of each color.
    pairs = {}
    for r0,r1 in rt:
        tiles = [tile(r0,r1,j) for j in range(n)]
        for j in range(n-1):
            a,b=tiles[j],tiles[j+1]
            col=color(a)
            if col and color(b)==col and mirror_equal(a,b):
                pairs.setdefault(col,set()).add((j,j+1))

    for r0,r1 in rt:
        tiles=[tile(r0,r1,j) for j in range(n)]
        colors=set(color(t) for t in tiles if occupied(t))
        for col in colors:
            for i,a in enumerate(tiles):
                if color(a)!=col:
                    continue
                # An already matched tile is complete; otherwise use the same-color
                # reflected pair demonstrated elsewhere in the grid.
                candidates=sorted(pairs.get(col,set()))
                partner=None
                for x,y in candidates:
                    if i==x and not occupied(tiles[y]): partner=y; break
                    if i==y and not occupied(tiles[x]): partner=x; break
                if partner is None:
                    # If this object has no learned pair, move it toward the center.
                    partner = i+1 if i < (n-1)/2 else i-1
                    if partner<0 or partner>=n or occupied(tiles[partner]):
                        continue
                src0,src1=ct[i]; dst0,dst1=ct[partner]
                for r in range(r0,r1):
                    for c in range(src0,src1):
                        v=grid[r][c]
                        if v:
                            out[r][dst1-1-(c-src0)] = v
    return out
"
}

