 "content": "def transform(grid):
    """Mirror each tile motif into its adjacent panel; paired panels use the left motif."""
    h, w = len(grid), len(grid[0])
    hdiv = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    vdiv = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    rb, cb = [-1] + hdiv + [h], [-1] + vdiv + [w]
    rt = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    ct = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    out = [row[:] for row in grid]
    for r0, r1 in rt:
        panels = []
        for c0, c1 in ct:
            panels.append([[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)])
        occupied = [any(v != 0 for row in p for v in row) for p in panels]
        colors = [next((v for row in p for v in row if v), 0) for p in panels]
        for i in range(len(ct) - 1):
            j = i + 1
            # A tile on the right that is narrower cannot hold a reflected copy;
            # in that edge case the motif is mirrored into the empty left panel.
            if occupied[i] and not occupied[j] and colors[i] != 0:
                if len(panels[i][0]) == len(panels[j][0]):
                    src, dst = i, j
                elif i > 0 and not occupied[i - 1] and len(panels[i][0]) == len(panels[i - 1][0]):
                    src, dst = i, i - 1
                else:
                    continue
                s0, s1 = ct[src]; d0, d1 = ct[dst]
                for r in range(r0, r1):
                    for c in range(s0, s1):
                        v = grid[r][c]
                        if v:
                            out[r][d1 - 1 - (c - s0)] = v
            elif occupied[i] and occupied[j] and colors[i] == colors[j]:
                # Adjacent same-color panels are a pair; use the left panel as
                # the canonical motif and reflect it into the right panel.
                if len(panels[i][0]) != len(panels[j][0]):
                    continue
                s0, s1 = ct[i]; d0, d1 = ct[j]
                for r in range(r0, r1):
                    for c in range(s0, s1):
                        v = grid[r][c]
                        out[r][d1 - 1 - (c - s0)] = v
        # Last panel may need to reflect inward if its right-hand neighbor is
        # too narrow to accommodate the motif.
        i = len(ct) - 1
        if i > 0 and occupied[i] and not occupied[i - 1] and colors[i] != 0:
            if len(panels[i][0]) > len(panels[i - 1][0]):
                s0, s1 = ct[i]; d0, d1 = ct[i - 1]
                for r in range(r0, r1):
                    for c in range(s0, s1):
                        v = grid[r][c]
                        if v:
                            out[r][d1 - 1 - (c - s0)] = v
    return out
