 "content": "def transform(grid):
    """Complete each occupied panel row with its horizontally reflected partner.

    Adjacent occupied panels form a pair: the right panel is the reflection of
    the left. A lone object is copied into the neighboring panel toward center.
    """
    h, w = len(grid), len(grid[0])
    hdiv = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    vdiv = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    rb, cb = [-1] + hdiv + [h], [-1] + vdiv + [w]
    bands = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    panels = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    out = [row[:] for row in grid]

    for r0, r1 in bands:
        n = len(panels)
        occupied = []
        for c0, c1 in panels:
            occupied.append(any(grid[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1)))
        paired = [False] * n
        # Make adjacent occupied panels an ordered reflected pair.
        i = 0
        while i < n - 1:
            if occupied[i] and occupied[i + 1]:
                s0, s1 = panels[i]
                d0, d1 = panels[i + 1]
                if s1 - s0 == d1 - d0:
                    for r in range(r0, r1):
                        for c in range(s0, s1):
                            out[r][d1 - 1 - (c - s0)] = grid[r][c]
                    paired[i] = paired[i + 1] = True
                    i += 2
                else:
                    i += 1
            else:
                i += 1
        # Lone panels create their mirrored partner one panel inward.
        for i in range(n):
            if not occupied[i] or paired[i]:
                continue
            j = i + 1 if i < n / 2 else i - 1
            if j < 0 or j >= n or occupied[j]:
                continue
            s0, s1 = panels[i]
            d0, d1 = panels[j]
            if s1 - s0 != d1 - d0:
                continue
            for r in range(r0, r1):
                for c in range(s0, s1):
                    v = grid[r][c]
                    if v != 0:
                        out[r][d1 - 1 - (c - s0)] = v
    return out
