    vdiv = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    rb, cb = [-1] + hdiv + [h], [-1] + vdiv + [w]
    bands = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    panels = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    n = len(panels)
    out = [row[:] for row in grid]

    def get_panel(r0, r1, j):
        c0, c1 = panels[j]
        return [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
    def color(a):
        return next((v for row in a for v in row if v != 0), 0)
    def occupied(a):
        return color(a) != 0
    def reflected(a, b):
        return len(a) == len(b) and all(len(x) == len(y) for x, y in zip(a, b)) and all(
            a[r][c] == b[r][len(b[0]) - 1 - c]
            for r in range(len(a)) for c in range(len(a[0])))

    # A visible completed motif defines the partner-panel pair for its color.
    pair_for_color = {}
    for r0, r1 in bands:
        tiles = [get_panel(r0, r1, j) for j in range(n)]
        for j in range(n - 1):
            col = color(tiles[j])
            if col and color(tiles[j + 1]) == col and reflected(tiles[j], tiles[j + 1]):
                pair_for_color.setdefault(col, (j, j + 1))

    for r0, r1 in bands:
        tiles = [get_panel(r0, r1, j) for j in range(n)]
        for col, (left, right) in pair_for_color.items():
            left_occ, right_occ = occupied(tiles[left]), occupied(tiles[right])
            if left_occ and right_occ:
                continue
            if not left_occ and not right_occ:
                continue
            src, dst = (left, right) if left_occ else (right, left)
            s0, s1 = panels[src]
            d0, d1 = panels[dst]
            if s1 - s0 != d1 - d0:
                continue
            for r in range(r0, r1):
                for c in range(s0, s1):
                    v = grid[r][c]
                    if v == col:
                        out[r][d1 - 1 - (c - s0)] = v
    return out
