    vc = [c for c in range(w) if grid[0][c] and all(grid[r][c] == grid[0][c] for r in range(h))]
    rb, cb = [-1] + hr + [h], [-1] + vc + [w]
    bands = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    panels = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    n = len(panels)
    out = [row[:] for row in grid]

    def get(r0, r1, j):
        a, b = panels[j]
        return [[grid[r][c] for c in range(a, b)] for r in range(r0, r1)]
    def color(block):
        return next((v for row in block for v in row if v), 0)
    def is_mirror(a, b):
        return len(a) == len(b) and len(a[0]) == len(b[0]) and all(
            a[r][c] == b[r][len(b[0]) - 1 - c]
            for r in range(len(a)) for c in range(len(a[0])))

