    # has no exact example, use its first adjacent same-color occurrence.
    pair_for_color = {}
    fallback = {}
    for r0, r1 in bands:
        blocks = [get(r0, r1, j) for j in range(n)]
        for j in range(n - 1):
            col = color(blocks[j])
            if col and col == color(blocks[j + 1]):
                fallback.setdefault(col, (j, j + 1))
                if is_mirror(blocks[j], blocks[j + 1]):
                    pair_for_color[col] = (j, j + 1)
    for col, pair in fallback.items():
        pair_for_color.setdefault(col, pair)

    for r0, r1 in bands:
        blocks = [get(r0, r1, j) for j in range(n)]
        for col, (left, right) in pair_for_color.items():
            left_has, right_has = color(blocks[left]) == col, color(blocks[right]) == col
